STEAL A POTATO - Farmer Spud, the quest NPC, and his clips
(BuildQuestNpc.lua, generated by tools/gen_kit.py)

Runs unattended: paste it into the command bar, or loadstring it. It builds, inside
ReplicatedStorage.PotatoKit (made if missing; attribute Studs = true):

    PotatoKit.QuestNpc
    PotatoKit.QuestNpcAnimations.Idle (KeyframeSequence)
    PotatoKit.QuestNpcAnimations.Wave (KeyframeSequence)
    PotatoKit.QuestNpcAnimations.Talk (KeyframeSequence)
    PotatoKit.QuestNpcAnimations.Cheer (KeyframeSequence)

120 Parts, every one a plain Roblox Part (Plastic with Inlet on all six faces; Neon and
SmoothPlastic ones Smooth), plus 280 keyframes. Each item above replaces anything with the
same name in the same folder (what an earlier run built); nothing else is touched.
Safe to run twice.
]]

